/* ==========================================
   Pixel Grocery Budget - Theme & Variables
   Palette:
   1. Background Tint: #e0eed5 (Pistachio screen)
   2. Pixel Dark/Ink: #1d2b1a (Deep arcade black/green)
   3. Card Surface:    #f7fbf2 (Warm pixel cream)
   4. Primary Accent:  #3b6e34 (Forest retro green)
   5. Alert/Over:      #b82d23 (Pixel brick red)
   ========================================== */
:root {
  --bg-color: #d6e8cb;
  --card-bg: #f5f9f0;
  --pixel-black: #1a2517;
  --pixel-green: #376a30;
  --pixel-hover: #4e8a45;
  --pixel-red: #ba2820;
  --pixel-red-bg: #fde8e7;
  --pixel-border-color: #1a2517;
  --font-system: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* Ensure hidden attribute is never overridden */
[hidden] {
  display: none !important;
}

body {
  background-color: var(--bg-color);
  font-family: var(--font-system);
  font-size: 16px;
  line-height: 1.4;
  color: var(--pixel-black);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
  /* Pixel grid pattern background */
  background-image: 
    linear-gradient(rgba(26, 37, 23, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(26, 37, 23, 0.05) 1px, transparent 1px);
  background-size: 8px 8px;
}

/* Pixel Card Container */
.pixel-card {
  background: var(--card-bg);
  width: 100%;
  max-width: 480px;
  padding: 24px;
  border: 4px solid var(--pixel-border-color);
  /* Stepped retro drop-shadow */
  box-shadow: 
    4px 4px 0 0 var(--pixel-border-color),
    8px 8px 0 0 rgba(26, 37, 23, 0.3);
}

/* Header & Pixel Icon */
.app-header {
  text-align: center;
  margin-bottom: 20px;
}

.pixel-icon {
  width: 24px;
  height: 24px;
  margin: 0 auto 8px auto;
  background-color: var(--pixel-green);
  /* Pure CSS 8-bit basket silhouette */
  box-shadow: 
    -8px 4px 0 0 var(--pixel-green),
    8px 4px 0 0 var(--pixel-green),
    -8px 8px 0 0 var(--pixel-green),
    8px 8px 0 0 var(--pixel-green),
    -4px 12px 0 0 var(--pixel-green),
    0 12px 0 0 var(--pixel-green),
    4px 12px 0 0 var(--pixel-green);
}

h1 {
  font-size: 24px;
  letter-spacing: -1px;
  font-weight: 900;
  text-transform: uppercase;
}

.subtitle {
  font-size: 14px;
  color: var(--pixel-green);
  font-weight: bold;
}

/* Form Controls */
.form-group {
  display: flex;
  flex-direction: column;
  margin-bottom: 12px;
}

.flex-grow {
  flex: 1;
}

label {
  font-size: 14px;
  font-weight: bold;
  margin-bottom: 4px;
  text-transform: uppercase;
}

input {
  font-family: var(--font-system);
  font-size: 16px;
  font-weight: bold;
  padding: 8px 10px;
  border: 3px solid var(--pixel-border-color);
  background-color: #ffffff;
  color: var(--pixel-black);
  outline: none;
}

input:focus-visible {
  background-color: #fafff5;
  border-color: var(--pixel-green);
  box-shadow: 0 0 0 2px var(--pixel-green);
}

.pixel-row {
  display: flex;
  gap: 8px;
  align-items: flex-end;
}

.pixel-grid-two {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

/* Pixel Buttons */
.pixel-btn {
  font-family: var(--font-system);
  font-size: 16px;
  font-weight: bold;
  padding: 8px 16px;
  cursor: pointer;
  border: 3px solid var(--pixel-border-color);
  background: #ffffff;
  color: var(--pixel-black);
  box-shadow: 3px 3px 0 0 var(--pixel-border-color);
  transition: none;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.pixel-btn:hover {
  background-color: #e6ebd8;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 0 var(--pixel-border-color);
}

.pixel-btn:focus-visible {
  outline: 2px dashed var(--pixel-black);
  outline-offset: 2px;
}

.btn-primary {
  background-color: var(--pixel-green);
  color: #ffffff;
  height: 42px;
  margin-bottom: 12px;
}

.btn-primary:hover {
  background-color: var(--pixel-hover);
}

.btn-accent {
  width: 100%;
  background-color: var(--pixel-black);
  color: #ffffff;
  padding: 10px;
  margin-top: 4px;
}

.btn-accent:hover {
  background-color: #333333;
}

.btn-remove {
  font-size: 13px;
  padding: 4px 8px;
  background-color: #ffffff;
  color: var(--pixel-red);
  border: 2px solid var(--pixel-border-color);
  box-shadow: 2px 2px 0 0 var(--pixel-border-color);
}

.btn-remove:hover {
  background-color: var(--pixel-red-bg);
}

.btn-remove:active {
  transform: translate(1px, 1px);
  box-shadow: 1px 1px 0 0 var(--pixel-border-color);
}

/* Summary Board */
.summary-panel {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 16px 0;
  padding: 12px 8px;
  background-color: #e8f0df;
  border: 3px solid var(--pixel-border-color);
}

.summary-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.stat-label {
  font-size: 12px;
  font-weight: bold;
  text-transform: uppercase;
}

.stat-value {
  font-size: 16px;
  font-weight: 900;
  margin-top: 2px;
  word-break: break-all;
}

/* Over-budget Dynamic State */
.over-budget {
  color: var(--pixel-red) !important;
  background-color: var(--pixel-red-bg) !important;
}

.stat-value.is-over {
  color: var(--pixel-red);
  animation: pulse-pixel 1s infinite alternate;
}

@keyframes pulse-pixel {
  0% { transform: scale(1); }
  100% { transform: scale(1.05); }
}

.alert-message {
  background-color: var(--pixel-red-bg);
  color: var(--pixel-red);
  border: 2px dashed var(--pixel-red);
  padding: 8px;
  text-align: center;
  font-weight: bold;
  font-size: 14px;
  margin-bottom: 16px;
}

/* Grocery Item List */
.items-panel {
  margin-top: 20px;
  border-top: 3px dashed var(--pixel-border-color);
  padding-top: 16px;
}

.items-panel h2 {
  font-size: 16px;
  margin-bottom: 12px;
  text-transform: uppercase;
}

.pixel-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 260px;
  overflow-y: auto;
  padding-right: 4px;
}

.empty-state {
  text-align: center;
  padding: 16px;
  font-style: italic;
  font-size: 14px;
  color: #555555;
}

.pixel-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 10px;
  background: #ffffff;
  border: 2px solid var(--pixel-border-color);
  box-shadow: 2px 2px 0 0 var(--pixel-border-color);
}

.item-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.item-name-text {
  font-weight: bold;
  word-break: break-word;
}

.item-calc-text {
  font-size: 13px;
  color: #444444;
}

.item-action {
  display: flex;
  align-items: center;
  gap: 8px;
}

.item-subtotal {
  font-weight: bold;
  font-size: 15px;
}

/* Responsive Styling */
@media (max-width: 400px) {
  .pixel-card {
    padding: 16px;
  }

  .summary-panel {
    grid-template-columns: 1fr;
    gap: 6px;
  }

  .summary-stat {
    flex-direction: row;
    justify-content: space-between;
    padding: 2px 8px;
  }
}

/**
 * Pixel Grocery Budget Tracker
 * Core Application Logic
 */
document.addEventListener('DOMContentLoaded', () => {
  // Application State
  const state = {
    budget: 0,
    items: []
  };

  // DOM Element References
  const budgetForm = document.getElementById('budget-form');
  const budgetInput = document.getElementById('budget-input');
  const itemForm = document.getElementById('item-form');
  const itemNameInput = document.getElementById('item-name');
  const itemPriceInput = document.getElementById('item-price');
  const itemQtyInput = document.getElementById('item-qty');
  const itemList = document.getElementById('item-list');
  const itemCountDisplay = document.getElementById('item-count');
  const emptyMsg = document.getElementById('empty-msg');
  const budgetDisplay = document.getElementById('budget-display');
  const totalDisplay = document.getElementById('total-display');
  const remainingDisplay = document.getElementById('remaining-display');
  const budgetAlert = document.getElementById('budget-alert');

  /**
   * Format a numerical value as currency ($X.XX)
   */
  function formatCurrency(amount) {
    return '$' + amount.toFixed(2);
  }

  /**
   * Calculates current total expenditure across all items
   */
  function calculateTotal() {
    return state.items.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  }

  /**
   * Re-evaluates totals, thresholds, and updates UI summary elements
   */
  function updateSummary() {
    const total = calculateTotal();
    const remaining = state.budget - total;
    const isOverBudget = state.budget > 0 && total > state.budget;

    budgetDisplay.textContent = formatCurrency(state.budget);
    totalDisplay.textContent = formatCurrency(total);
    remainingDisplay.textContent = formatCurrency(remaining);
    itemCountDisplay.textContent = String(state.items.length);

    if (isOverBudget) {
      totalDisplay.classList.add('is-over');
      remainingDisplay.classList.add('is-over');
      budgetAlert.hidden = false;
    } else {
      totalDisplay.classList.remove('is-over');
      remainingDisplay.classList.remove('is-over');
      budgetAlert.hidden = true;
    }
  }

  /**
   * Render grocery list items to DOM
   */
  function renderItems() {
    // Clear previous items except empty message
    itemList.innerHTML = '';

    if (state.items.length === 0) {
      itemList.appendChild(emptyMsg);
      emptyMsg.hidden = false;
      return;
    }

    state.items.forEach((item) => {
      const li = document.createElement('li');
      li.className = 'pixel-item';

      const infoDiv = document.createElement('div');
      infoDiv.className = 'item-info';

      const nameSpan = document.createElement('span');
      nameSpan.className = 'item-name-text';
      nameSpan.textContent = item.name;

      const calcSpan = document.createElement('span');
      calcSpan.className = 'item-calc-text';
      calcSpan.textContent = `${item.quantity} × ${formatCurrency(item.price)}`;

      infoDiv.appendChild(nameSpan);
      infoDiv.appendChild(calcSpan);

      const actionDiv = document.createElement('div');
      actionDiv.className = 'item-action';

      const subtotalSpan = document.createElement('span');
      subtotalSpan.className = 'item-subtotal';
      subtotalSpan.textContent = formatCurrency(item.price * item.quantity);

      const removeBtn = document.createElement('button');
      removeBtn.type = 'button';
      removeBtn.className = 'pixel-btn btn-remove';
      removeBtn.setAttribute('aria-label', `Remove ${item.name} from list`);
      removeBtn.textContent = 'DEL';

      removeBtn.addEventListener('click', () => {
        removeItem(item.id);
      });

      actionDiv.appendChild(subtotalSpan);
      actionDiv.appendChild(removeBtn);

      li.appendChild(infoDiv);
      li.appendChild(actionDiv);
      itemList.appendChild(li);
    });
  }

  /**
   * Adds an item to the grocery state
   */
  function addItem(name, price, quantity) {
    const newItem = {
      id: Date.now().toString(36) + Math.random().toString(36).substring(2),
      name: name.trim(),
      price: parseFloat(price),
      quantity: parseInt(quantity, 10)
    };
    state.items.push(newItem);
    renderItems();
    updateSummary();
  }

  /**
   * Removes an item by ID from state
   */
  function removeItem(id) {
    state.items = state.items.filter(item => item.id !== id);
    renderItems();
    updateSummary();
  }

  // Event Listeners
  budgetForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const parsedBudget = parseFloat(budgetInput.value);
    if (!isNaN(parsedBudget) && parsedBudget >= 0) {
      state.budget = parsedBudget;
      updateSummary();
    }
  });

  itemForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = itemNameInput.value.trim();
    const price = parseFloat(itemPriceInput.value);
    const qty = parseInt(itemQtyInput.value, 10);

    if (name && !isNaN(price) && price > 0 && !isNaN(qty) && qty > 0) {
      addItem(name, price, qty);
      itemForm.reset();
      itemQtyInput.value = '1';
      itemNameInput.focus();
    }
  });

  // Initial rendering
  renderItems();
  updateSummary();
});
